{"path": "shopkit/shipping/options.py", "content": """"Express-delivery eligibility, mirroring the warehouse's wave allocation.

Checkout must only offer express when the warehouse would actually put the order into an express
wave, so this mirrors the rules in shopkit.warehouse.waves.allocate_wave:

- an order that contains a hazmat SKU never goes into an express wave (express leaves by air);
- an express wave is created per site and per service, so at least one of the given sites must have
  express in its services.

Stock is deliberately *not* considered here: an item without stock is backordered and its order
still joins the express wave it was placed in, so checkout keeps offering express while the SKU is
on sale.
"""
from shopkit.config import SETTINGS
from shopkit.warehouse.sites import Site
from shopkit.warehouse.waves import EXPRESS


def express_available(skus: list[str], sites: list[Site], hazmat_skus: frozenset[str]) -> bool:
    """True when the warehouse would put an order with these SKUs into an express wave.

    skus: the cart's SKUs (duplicates are fine); sites: the warehouse sites that could ship it;
    hazmat_skus: the SKUs classed as dangerous goods.
    """
    wanted = {sku for sku in skus}
    if wanted & hazmat_skus:
        return False
    eligible = [s for s in sites if s.country == SETTINGS.store_country or SETTINGS.flag("cross_border_fulfillment")]
    if not eligible:
        eligible = list(sites)            # same hotfix as allocate_wave: never strand on the country filter
    return any(EXPRESS in s.services for s in eligible)
